package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Venda; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface VendaRepository extends JpaRepository<Venda,String> { Optional<Venda> findByIdempotencyKey(String key); @EntityGraph(attributePaths={"cliente","vendedor","itens","itens.produto"}) @Query("select v from Venda v where v.id=:id") Optional<Venda> detail(@Param("id")String id); @Query("select coalesce(sum(v.totalVenda),0) from Venda v where v.status='FINALIZADA' and v.dataVenda between :from and :to") BigDecimal totalFinalized(@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select v from Venda v where v.cliente.id=:clientId and v.status='FINALIZADA' order by v.dataVenda desc") List<Venda> finalizedByClient(@Param("clientId")String clientId);
 // Histórico do cliente: todas as vendas (inclusive canceladas) com os itens, mais recentes primeiro.
 @EntityGraph(attributePaths={"itens"}) @Query("select distinct v from Venda v where v.cliente.id=:clientId order by v.dataVenda desc, v.numeroVenda desc") List<Venda> historyByClient(@Param("clientId")String clientId); @Query("select v from Venda v join fetch v.cliente order by v.dataVenda desc") List<Venda> listWithClient(); @Query("select coalesce(sum(i.quantidade*coalesce(i.custoUnitario,0)),0) from VendaItem i where i.venda.status='FINALIZADA' and i.venda.dataVenda between :from and :to") BigDecimal costOfGoodsSold(@Param("from")LocalDate from,@Param("to")LocalDate to);  @Query("select count(v) from Venda v where v.status='FINALIZADA' and v.dataVenda between :from and :to") long countFinalized(@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select v.dataVenda, sum(v.totalVenda) from Venda v where v.status='FINALIZADA' and v.dataVenda between :from and :to group by v.dataVenda order by v.dataVenda") List<Object[]> dailyTotals(@Param("from")LocalDate from,@Param("to")LocalDate to); @Query("select i.produtoNomeSnapshot, sum(i.quantidade), sum(i.subtotal) from VendaItem i where i.venda.status='FINALIZADA' and i.venda.dataVenda between :from and :to group by i.produtoNomeSnapshot order by sum(i.subtotal) desc") List<Object[]> topProdutos(@Param("from")LocalDate from,@Param("to")LocalDate to,org.springframework.data.domain.Pageable limite);
 // Itens das vendas finalizadas no período, para os relatórios por produto (a receita é rateada pelo desconto em Java).
 @Query("select p.id, i.produtoNomeSnapshot, i.quantidade, i.subtotal, i.custoUnitario, v.subtotal, v.totalVenda, p.precoCusto from VendaItem i join i.venda v join i.produto p where v.status='FINALIZADA' and v.dataVenda between :from and :to") List<Object[]> itensVendidos(@Param("from")LocalDate from,@Param("to")LocalDate to);
 // Vendas finalizadas por vendedor (nome nulo = venda sem vendedor).
 @Query("select f.nome, count(v), sum(v.totalVenda), sum(v.desconto) from Venda v left join v.vendedor f where v.status='FINALIZADA' and v.dataVenda between :from and :to group by f.id, f.nome") List<Object[]> vendasPorVendedor(@Param("from")LocalDate from,@Param("to")LocalDate to);
 }
